import json, sys
for line in sys.stdin:
    if line.strip().startswith('{'):
        data = json.loads(line)
        for item in data.get('items', []):
            print(f\"  {item['start']['dateTime']}  {item['summary']}  [{item['location']}]  (id: {item['id']})\")" 2>&1
